CREATE TABLE reports(id uuid PRIMARY KEY,employee_id uuid NOT NULL,employee_name text NOT NULL,manager_id uuid,title text NOT NULL,status text NOT NULL DEFAULT 'DRAFT',revision int NOT NULL DEFAULT 0,row_version int NOT NULL DEFAULT 0,payload jsonb NOT NULL,policy_id uuid,job_id uuid,ai_status text NOT NULL DEFAULT 'NONE',ai_result jsonb,decision jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE receipts(id uuid PRIMARY KEY,report_id uuid NOT NULL REFERENCES reports(id),name text NOT NULL,mime text NOT NULL,sha256 text NOT NULL,data bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE revisions(report_id uuid NOT NULL REFERENCES reports(id),revision int NOT NULL,payload jsonb NOT NULL,policy_id uuid NOT NULL,submitted_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(report_id,revision));
CREATE TABLE review_jobs(id uuid PRIMARY KEY,report_id uuid NOT NULL REFERENCES reports(id),revision int NOT NULL,status text NOT NULL DEFAULT 'PENDING',result jsonb,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE outbox(id uuid PRIMARY KEY,event jsonb NOT NULL,sent_at timestamptz,attempts int NOT NULL DEFAULT 0,last_error text);
CREATE TABLE audit(id bigserial PRIMARY KEY,report_id uuid NOT NULL REFERENCES reports(id),actor_id text NOT NULL,action text NOT NULL,note text NOT NULL DEFAULT '',at timestamptz NOT NULL DEFAULT now());
CREATE INDEX reports_owner ON reports(employee_id);CREATE INDEX reports_manager ON reports(manager_id);CREATE INDEX outbox_pending ON outbox(sent_at) WHERE sent_at IS NULL;
